-- BooleanTest expressions: IS [NOT] TRUE / FALSE / UNKNOWN
SELECT x IS TRUE FROM t;

SELECT x IS NOT TRUE FROM t;

SELECT x IS FALSE, y IS NOT FALSE FROM t;

SELECT x IS UNKNOWN, y IS NOT UNKNOWN FROM t;

SELECT * FROM t WHERE (a > b) IS NOT TRUE;

SELECT (a AND b) IS TRUE FROM t;

UPDATE t SET v = 1 WHERE active IS NOT FALSE;
